package app.copyreader.clean;

import java.util.Base64;

/** Bounded local PNGs generated by the shelf canvas; no remote or active content. */
final class LocalImageProtocol {
    private static final String PREFIX = "data:image/png;base64,";
    private static final int MAX_BYTES = 256 * 1024;
    private static final int MAX_ENCODED = ((MAX_BYTES + 2) / 3) * 4;

    static byte[] png(String url) {
        if (url == null || !url.startsWith(PREFIX)) return null;
        int length = url.length() - PREFIX.length();
        if (length < 44 || length > MAX_ENCODED) return null;
        try {
            byte[] bytes = Base64.getDecoder().decode(url.substring(PREFIX.length()));
            if (bytes.length < 33 || bytes.length > MAX_BYTES) return null;
            int[] signature = {137,80,78,71,13,10,26,10};
            for (int i=0;i<signature.length;i++) if ((bytes[i]&255)!=signature[i]) return null;
            if (number(bytes,8)!=13 || bytes[12]!='I' || bytes[13]!='H' || bytes[14]!='D' || bytes[15]!='R') return null;
            long width=number(bytes,16),height=number(bytes,20);
            if (width<1 || height<1 || width>1024 || height>1024) return null;
            return bytes;
        } catch (IllegalArgumentException ignored) { return null; }
    }

    private static long number(byte[] bytes,int offset) {
        long result=0;
        for(int i=0;i<4;i++)result=(result<<8)|(bytes[offset+i]&255);
        return result;
    }
}
